/**
 * The API catalogue, generated from the published docs on 2026-08-12.
 *
 * Sources, all first-party:
 *   Unified      https://docs.uniblock.dev/reference/api-json.json (OpenAPI)
 *   Hyperliquid  https://docs.uniblock.dev/reference/api-json/hyperliquid-info-api-json.json
 *   Direct       https://docs.uniblock.dev/reference/direct/direct-providers/*
 *
 * Every path, verb, title, category and CU estimate below is transcribed, not
 * invented. Endpoints are stored as tuples rather than objects because there
 * are a few thousand of them and the object form tripled the file for no gain.
 */

export type Method = 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH' | 'WS';

export type ApiEndpoint = {
  method: Method;
  /** Request path as published in the reference. */
  path: string;
  /** Human-readable title, or the reference's own description of the call. */
  title: string;
  category: string;
  /** Estimated compute units, as published. Direct endpoints only. */
  cu?: number;
};

/** [method, path, title, category, cu?], see the note above. */
type Row = [Method, string, string, string, number?];

const rows = (list: Row[]): ApiEndpoint[] =>
  list.map(([method, path, title, category, cu]) => ({ method, path, title, category, cu }));

